// n8n Code Node (JavaScript)
// Entrada: items[] con campos: Pedido (string JSON), Total, Estatus, Nombre, Telefono, Correo
// Salida: un item por destinatario con { to, subject, html }

function currencyMXN(n) {
  const num = Number(n);
  if (Number.isNaN(num)) return n;
  return num.toLocaleString('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 2 });
}

// Escapar texto simple para HTML
function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Badge y fila por estatus
const STATUS_MAP = {
  'activo':   { label: 'Activa',   class: 'badge badge--ok',    row: 'row row--ok' },
  'por vencer': { label: 'Por vencer', class: 'badge badge--warn',  row: 'row row--warn' },
  'vencido':  { label: 'Vencida',  class: 'badge badge--danger', row: 'row row--danger' },
};

function productosResumen(pedidoStr) {
  try {
    const obj = typeof pedidoStr === 'string' ? JSON.parse(pedidoStr) : pedidoStr;
    const prods = Array.isArray(obj?.productos) ? obj.productos : [];
    if (!prods.length) return '-';
    return prods.map(p => `${p.nombre} (x${p.cantidad})`).join(', ');
  } catch {
    return '-';
  }
}

function buildHTML(nombre, correo, pedidos) {
  // Estadísticos por estatus
  const counts = { activo: 0, 'por vencer': 0, vencido: 0 };
  let totalSuma = 0;

  // Pre-render filas
  const rows = pedidos.map((p, idx) => {
    const estatusKey = (String(p.Estatus || '').trim().toLowerCase());
    const meta = STATUS_MAP[estatusKey] ?? { label: esc(p.Estatus || ''), class: 'badge', row: 'row' };
    const totalNum = Number(p.Total);
    if (!Number.isNaN(totalNum)) totalSuma += totalNum;
    if (counts[estatusKey] !== undefined) counts[estatusKey]++;

    return `
      <tr class="${meta.row}">
        <td class="col col--idx">${idx + 1}</td>
        <td class="col col--status"><span class="${meta.class}">${esc(meta.label)}</span></td>
        <td class="col col--total">${currencyMXN(p.Total)}</td>
        <td class="col col--productos">${esc(productosResumen(p.Pedido))}</td>
      </tr>
    `;
  }).join('');

  const hoy = new Date().toLocaleDateString('es-MX', { year: 'numeric', month: 'long', day: '2-digit' });

  return `<!DOCTYPE html>
<html lang="es">
