      </div>

      <div class="hello">
        Hola <strong>${esc(nombre)}</strong>, aquí Rafita de <span class="brand">Carnicería San Rafa</span>.  
        Te comparto el resumen de tus facturas de este mes.
      </div>

      <div class="summary">
        <span class="pill">Activas: ${counts.activo}</span>
        <span class="pill">Por vencer: ${counts['por vencer']}</span>
        <span class="pill">Vencidas: ${counts.vencido}</span>
        <span class="pill">Total acumulado: <strong>${currencyMXN(totalSuma)}</strong></span>
      </div>

      <div class="table-wrap">
        <table role="table" aria-label="Listado de facturas">
          <thead>
            <tr>
              <th class="col col--idx">#</th>
              <th class="col col--status">Estatus</th>
              <th class="col col--total">Total</th>
              <th class="col col--productos">Productos</th>
            </tr>
          </thead>
          <tbody>
            ${rows}
          </tbody>
        </table>
      </div>

      <div class="footer">
        © ${new Date().getFullYear()} <span class="brand">Carnicería San Rafa</span>.  
        Sucursal Centro · Tel. 555-123-4567 · Horario: Lun-Dom 8:00–19:00.
      </div>
    </div>
  </div>
</body>
</html>`;
}

const input = items.map(i => i.json || {});
// Agrupar por correo (un email por destinatario)
const byEmail = new Map();
for (const row of input) {
  const correo = String(row.Correo || '').trim().toLowerCase() || 'sin_correo@local';
  if (!byEmail.has(correo)) byEmail.set(correo, []);
  byEmail.get(correo).push(row);
}

// Construir salida (un item por correo)
const out = [];
for (const [correo, pedidos] of byEmail.entries()) {
  const nombre = pedidos[0]?.Nombre || 'Cliente';
  const subject = `Tus facturas del mes - Carnicería San Rafa`;
  const html = buildHTML(nombre, correo, pedidos);
  out.push({ json: { to: correo, subject, html, nombre } });
}

return out;
